// Package web embeds the built SvelteKit SPA (web/build) into the binary.
//
// web/build is generated by "make web" and is not committed, except for the
// .gitkeep placeholder that keeps the embed pattern valid on a fresh checkout.
// Without a build, the embedded tree contains no index.html and
// internal/webui serves a "web UI not built" notice instead.
package web

import (
	"embed"
	"io/fs"
)

//go:embed all:build
var buildFS embed.FS

// Build returns the embedded SPA rooted at the build directory.
func Build() fs.FS {
	sub, err := fs.Sub(buildFS, "build")
	if err != nil {
		// Cannot happen: "build" is guaranteed by the embed pattern above.
		panic(err)
	}
	return sub
}
